<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,Arial;font-size:10px}h2{margin-bottom:4px}table{width:100%;border-collapse:collapse;margin:10px 0 20px}th,td{border:1px solid #777;padding:5px}th{background:#eee}.right{text-align:right}</style></head><body><h2>Laporan Keuangan SPPG</h2><div><?= esc($sppg_name) ?></div><div>Periode: <?= esc($from?:'awal') ?> s/d <?= esc($to?:'akhir') ?></div><h3>Pengajuan/Pengadaan Bahan</h3><table><thead><tr><th>Tanggal</th><th>Kode</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($purchases as $r):?><tr><td><?= date('d/m/Y',strtotime($r['tanggal'])) ?></td><td><?= esc($r['kode_transaksi']) ?></td><td><?= esc($r['status']) ?></td><td class="right">Rp <?= number_format($r['grand_total'],0,',','.') ?></td></tr><?php endforeach;?></tbody></table><h3>Pengeluaran Aslap</h3><table><thead><tr><th>Tanggal</th><th>Kategori</th><th>Uraian</th><th>Nominal</th></tr></thead><tbody><?php foreach($expenses as $r):?><tr><td><?= date('d/m/Y',strtotime($r['tanggal'])) ?></td><td><?= esc($r['kategori']) ?></td><td><?= esc($r['uraian']) ?></td><td class="right">Rp <?= number_format($r['nominal'],0,',','.') ?></td></tr><?php endforeach;?></tbody></table><h3>Petty Cash</h3><table><thead><tr><th>Tanggal</th><th>Jenis</th><th>Kategori</th><th>Uraian</th><th>Jumlah</th><th>Saldo Akhir</th></tr></thead><tbody><?php foreach(($petty_cash??[]) as $r): ?><tr><td><?= date('d/m/Y',strtotime($r['tanggal'])) ?></td><td><?= esc(ucfirst($r['jenis'])) ?></td><td><?= esc($r['kategori']) ?></td><td><?= esc($r['deskripsi']??'—') ?></td><td class="right">Rp <?= number_format((float)$r['jumlah'],0,',','.') ?></td><td class="right">Rp <?= number_format((float)$r['saldo_akhir'],0,',','.') ?></td></tr><?php endforeach; ?></tbody></table></body></html>
